begin; update public.game_members set kind='student',role_title='Депутат Государственной Думы' where game_id='541b6fde-16d5-4225-8f67-1fc2c7c15523' and user_id='89de1d45-8973-4f38-980d-26042af9e53e'; select set_config('request.jwt.claim.sub','9fdf732c-1a84-4435-979d-e0272c2b81db',true); set local role authenticated; do $$ declare g uuid:='541b6fde-16d5-4225-8f67-1fc2c7c15523';u uuid:='89de1d45-8973-4f38-980d-26042af9e53e';blocked boolean:=false;t text;begin begin perform public.appoint_game_office(g,u,'Министр здравоохранения','Проверка несовместимости старой должности',false);exception when others then blocked:=true;end; if not blocked then raise exception 'FAIL legacy incompatibility';end if; perform public.appoint_game_office(g,u,'Министр здравоохранения','Явное учебное исключение преподавателя',true); select role_title into t from public.game_members where game_id=g and user_id=u; if t<>'Депутат Государственной Думы' then raise exception 'FAIL current office changed';end if; if (select count(*) from public.game_office_assignments where game_id=g and user_id=u and status='active')<>2 then raise exception 'FAIL multiple offices';end if;end;$$; reset role; rollback;
